from __future__ import annotations
from math import isclose

def energy(connectivity: float, u: float, v: float) -> float:
    return connectivity * (u - v) ** 2 / 2.0

def variance(u: float, v: float) -> float:
    return (u - v) ** 2 / 2.0

def verify(connectivity: float, pairs: list[tuple[float, float]]) -> None:
    for u, v in pairs:
        lhs = energy(connectivity, u, v)
        rhs = connectivity * variance(u, v)
        print(u, v, lhs, rhs)
        assert isclose(lhs, rhs)

if __name__ == "__main__":
    verify(3.5, [(-2.0, 1.0), (0.0, 0.0), (1.25, -0.75)])

from __future__ import annotations
from collections.abc import Callable

def radius_witness(radius: float) -> tuple[Callable[[float], float], float]:
    if radius <= 0.0:
        raise ValueError("radius must be positive")
    return lambda x: radius / 2.0 - x, radius / 2.0

def gain_witness(bound: float) -> Callable[[float], float]:
    if bound < 0.0:
        raise ValueError("bound must be nonnegative")
    return lambda x: (bound + 1.0) * x

if __name__ == "__main__":
    f, y = radius_witness(2.4)
    print(f(0.0), y, f(y))
    g = gain_witness(7.0)
    print(abs(g(1.0) - g(0.0)))

