from __future__ import annotations
from dataclasses import dataclass
from math import sqrt

@dataclass(frozen=True)
class Certificate:
    state_lipschitz: float
    output_lipschitz: float
    radius: float

def certificate(connectivity: float, state_gain: float, readout_gain: float, margin: float) -> Certificate:
    if min(connectivity, state_gain, readout_gain, margin) <= 0.0:
        raise ValueError("all parameters must be positive")
    state_lipschitz = state_gain / sqrt(connectivity)
    output_lipschitz = readout_gain * state_lipschitz
    return Certificate(state_lipschitz, output_lipschitz, margin / output_lipschitz)

if __name__ == "__main__":
    print(certificate(4.0, 2.0, 3.0, 1.5))

from __future__ import annotations
from collections.abc import Callable, Sequence

def check_pairs(state: Callable[[float], float], samples: Sequence[float], connectivity: float, gain: float, tolerance: float = 1e-12) -> tuple[bool, float]:
    worst = 0.0
    for i, x in enumerate(samples):
        for y in samples[i:]:
            residual = connectivity * (state(x) - state(y)) ** 2 - gain ** 2 * (x - y) ** 2
            worst = max(worst, residual)
    return worst <= tolerance, worst

if __name__ == "__main__":
    print(check_pairs(lambda x: x, [-1.0, 0.0, 1.0], 4.0, 2.0))

